    """Process section0.xml - customer info, pricing band, etc."""
    filepath = os.path.join(extract_dir, 'Contents', 'section0.xml')

    tree = ET.parse(filepath)
    root = tree.getroot()

    ns = {'hp': 'http://www.hancom.co.kr/hwpml/2010/HWPML'}

    # Track modified paragraphs
    modified_paras = set()

    # Find all <hp:p> elements
    for para in root.findall('.//hp:p', ns):
        para_id = para.get('id', 'unknown')
        modified = False

        # Step 1: Consolidate <hp:t> within each <hp:run>
        for run in para.findall('.//hp:run', ns):
            consolidate_t_tags(run, ns)

        # Step 2: Perform text replacements
        for run in para.findall('.//hp:run', ns):
            for t_tag in run.findall('hp:t', ns):
                if t_tag.text:
                    orig_text = t_tag.text
                    new_text = orig_text

                    # Replace customer name - handle split case
                    if 'Northwind' in orig_text or 'Retail' in orig_text:
                        new_text = new_text.replace('Northwind ', '').replace('Retail', '')
                        if new_text.strip() == '':
                            new_text = updates['customer']
                        elif 'Northwind' in orig_text and 'Retail' not in orig_text:
                            new_text = new_text.replace('Northwind', '').strip()
                            if new_text:
                                new_text = updates['customer'] + ' ' + new_text
                            else:
                                new_text = updates['customer']
                        elif 'Retail' in orig_text and 'Northwind' not in orig_text:
                            new_text = new_text.replace('Retail', '').strip()
                            if new_text:
                                new_text = new_text + ' ' + updates['customer']
                            else:
                                new_text = updates['customer']

                    # Replace owner
                    if old_values['owner'] in orig_text:
                        new_text = new_text.replace(old_values['owner'], updates['owner_name'])

                    # Replace window dates
                    if old_values['window_start'] in orig_text:
                        new_text = new_text.replace(old_values['window_start'], updates['window_start'])
                    if old_values['window_end'] in orig_text:
                        new_text = new_text.replace(old_values['window_end'], updates['window_end'])

                    # Replace band
                    if old_values['band'] in orig_text:
                        new_text = new_text.replace(old_values['band'], updates['band'])

                    # Replace escalation
                    if old_values['escalation'] in orig_text:
                        new_text = new_text.replace(old_values['escalation'], updates['escalation_email'])

                    # Replace note
                    if old_values['note'] in orig_text:
                        new_text = new_text.replace(old_values['note'], updates['note'])

                    if new_text != orig_text:
                        t_tag.text = new_text
                        modified = True

        if modified:
            modified_paras.add(para_id)
            # Step 3: Remove <hp:lineSegArray> from modified paragraphs
            for linesegarray in para.findall('hp:lineSegArray', ns):
                para.remove(linesegarray)

    # Handle the special case where customer name is split across two <hp:t> elements
    # in <hp:run> elements within the same paragraph
    for para in root.findall('.//hp:p', ns):
        para_id = para.get('id', 'unknown')
        runs = para.findall('hp:run', ns)

        # Check if this paragraph has "Northwind" and "Retail" in separate runs/t tags
        full_text = ''
        for run in runs:
            for t_tag in run.findall('hp:t', ns):
                if t_tag.text:
                    full_text += t_tag.text

        # If paragraph contains customer info with old values
        if 'Northwind' in full_text and 'Retail' in full_text:
            # Find the first run with text and replace it with full customer name
            for run in runs:
                t_tags = run.findall('hp:t', ns)
                for i, t_tag in enumerate(t_tags):
                    if t_tag.text and ('Northwind' in t_tag.text or 'Retail' in t_tag.text):
                        if i == 0:
                            t_tag.text = updates['customer']
                        else:
                            t_tag.text = ''
                        modified_paras.add(para_id)

            # Remove other runs that have the remaining parts
            for run in runs:
                t_tags = run.findall('hp:t', ns)
                for t_tag in t_tags:
                    if t_tag.text and ('Northwind' in t_tag.text or 'Retail' in t_tag.text):
                        if t_tag.text != updates['customer']:
                            t_tag.text = ''

            # Remove lineSegArray
            for linesegarray in para.findall('hp:lineSegArray', ns):
                para.remove(linesegarray)

    # Write back
    tree.write(filepath, encoding='UTF-8', xml_declaration=True)

def process_section1(extract_dir, old_values, followups, updates):
    """Process section1.xml - follow-ups and appendix."""
    filepath = os.path.join(extract_dir, 'Contents', 'section1.xml')

    tree = ET.parse(filepath)
    root = tree.getroot()

    ns = {'hp': 'http://www.hancom.co.kr/hwpml/2010/HWPML'}

    # Find follow-up paragraphs (contain "1." "2." "3.")
    followup_paras = []  # (para_element, old_number)

    for para in root.findall('.//hp:p', ns):
        para_id = para.get('id', 'unknown')

        # Consolidate <hp:t> within each <hp:run> first
        for run in para.findall('.//hp:run', ns):
            consolidate_t_tags(run, ns)

        # Check if this is a follow-up line (starts with "1." "2." "3.")
        full_text = get_para_text(para, ns)
        if full_text.startswith('1.') or full_text.startswith('2.') or full_text.startswith('3.'):
            num = int(full_text.split('.')[0])
            followup_paras.append((para, num))

        # Also need to replace window dates in this section
        for run in para.findall('.//hp:run', ns):
            for t_tag in run.findall('hp:t', ns):
                if t_tag.text:
                    orig_text = t_tag.text
                    new_text = orig_text

                    # Replace window dates
                    if old_values['window_start'] in orig_text:
                        new_text = new_text.replace(old_values['window_start'], updates['window_start'])
                    if old_values['window_end'] in orig_text:
                        new_text = new_text.replace(old_values['window_end'], updates['window_end'])

                    if new_text != orig_text:
                        t_tag.text = new_text
                        # Remove lineSegArray from this paragraph
                        for linesegarray in para.findall('hp:lineSegArray', ns):
                            para.remove(linesegarray)

    # Sort followup paragraphs by their number
    followup_paras.sort(key=lambda x: x[1])

    # Replace follow-up items
    for i, (para, old_num) in enumerate(followup_paras):
        if i < len(followups):
            new_item = followups[i]['item']
            # Find the first run with text and replace it
            for run in para.findall('hp:run', ns):
                for t_tag in run.findall('hp:t', ns):
                    if t_tag.text:
                        # Replace the entire text with new follow-up
                        t_tag.text = f"{i+1}. {new_item}"
                        break
                else:
                    continue
                break

            # Remove lineSegArray from this paragraph
            for linesegarray in para.findall('hp:lineSegArray', ns):
                para.remove(linesegarray)

    # Write back
    tree.write(filepath, encoding='UTF-8', xml_declaration=True)

def consolidate_t_tags(run, ns):
    """Consolidate multiple <hp:t> tags within a run into one."""
    t_tags = run.findall('hp:t', ns)
    if len(t_tags) <= 1:
        return

    # Merge all text into the first t tag
    merged_text = ''
    for t_tag in t_tags:
        if t_tag.text:
            merged_text += t_tag.text

    # Set first tag text, remove others
    t_tags[0].text = merged_text
    for t_tag in t_tags[1:]:
        run.remove(t_tag)

def get_para_text(para, ns):
    """Get full text content of a paragraph."""
    texts = []
    for run in para.findall('.//hp:run', ns):
        for t_tag in run.findall('hp:t', ns):
            if t_tag.text:
                texts.append(t_tag.text)
    return ''.join(texts)

def create_hwpx(extract_dir, output_path):
    """Create HWPX file from extracted contents."""
    mimetype_path = os.path.join(extract_dir, 'mimetype')

    with zipfile.ZipFile(output_path, 'w', zipfile.ZIP_DEFLATED) as zipf:
        # Find mimetype file
        mimetype_found = False
        for root, dirs, files in os.walk(extract_dir):
            for file in files:
                filepath = os.path.join(root, file)
                relpath = os.path.relpath(filepath, extract_dir)

                if file == 'mimetype':
                    # Add mimetype first with stored compression (no compression)
                    zipf.write(filepath, relpath, compress_type=zipfile.ZIP_STORED)
                    mimetype_found = True
                else:
                    zipf.write(filepath, relpath, compress_type=zipfile.ZIP_DEFLATED)

        if not mimetype_found:
            print("Warning: mimetype file not found")

