    # Clean and extract HWPX (ZIP)
    if os.path.exists(extract_dir):
        shutil.rmtree(extract_dir)
    os.makedirs(extract_dir, exist_ok=True)

    with zipfile.ZipFile(hwpx_path, 'r') as zip_ref:
        zip_ref.extractall(extract_dir)

    # Register namespace to preserve prefix
    ET.register_namespace('hp', 'http://www.hancom.co.kr/hwpml/2010/HWPML')

    # Define old values from original XML (these are what we need to replace)
    old_values = {
        'customer': 'Northwind Retail',
        'owner': '이전담당자',
        'window_start': '2025-04-01',
        'window_end': '2025-04-15',
        'band': 'Standard-18M',
        'escalation': 'ops-old@northwind.example',
        'note': '기존 메모를 새 메모로 바꾸세요.'
    }

    process_section0(extract_dir, old_values, updates)
    process_section1(extract_dir, old_values, followups, updates)

    # Re-zip as HWPX
    create_hwpx(extract_dir, output_path)

    print(f"Updated HWPX created at: {output_path}")

    # Validate
    validate_output(output_path, updates, followups)

def process_section0(extract_dir, old_values, updates):
    """Process section0.xml - customer info, pricing band, etc."""
    filepath = os.path.join(extract_dir, 'Contents', 'section0.xml')

