                for run in sublist_para.findall('.//hp:run', ns):
                    sub_modified = False
                    for t_tag in run.findall('hp:t', ns):
                        if t_tag.text:
                            orig_text = t_tag.text
                            new_text = orig_text

                            # Replace band
                            if old_values['band'] in orig_text:
                                new_text = new_text.replace(old_values['band'], updates['band'])

                            # Replace escalation
                            if old_values['escalation'] in orig_text:
                                new_text = new_text.replace(old_values['escalation'], updates['escalation_email'])

                            if new_text != orig_text:
                                t_tag.text = new_text
                                sub_modified = True

                    if sub_modified:
                        modified = True
                        # Remove lineSegArray from this sublist paragraph
                        remove_lineSegArray(sublist_para, ns)

        if modified:
            modified_paras.add(para_id)
            # Step 3: Remove <hp:lineSegArray> from modified paragraphs
            remove_lineSegArray(para, ns)

    # Write back
    tree.write(filepath, encoding='UTF-8', xml_declaration=True)

def replace_in_para_with_split_handling(para, old_parts, new_value, ns):
    """Handle customer name split across multiple runs/t elements."""
    # Consolidate t tags first
    for run in para.findall('.//hp:run', ns):
