    # Get all text elements
    full_text = ''
    text_elements = []
    for run in para.findall('.//hp:run', ns):
        for t_tag in run.findall('hp:t', ns):
            if t_tag.text:
                full_text += t_tag.text
                text_elements.append((run, t_tag))

    # Check if old value is present
    if 'Northwind' in full_text or 'Retail' in full_text:
        # Replace in first text element with "고객사:"
        for run in para.findall('.//hp:run', ns):
            for t_tag in run.findall('hp:t', ns):
