    return False

def process_section1(extract_dir, old_values, followups, updates):
    """Process section1.xml - follow-ups and appendix."""
    filepath = os.path.join(extract_dir, 'Contents', 'section1.xml')

    tree = ET.parse(filepath)
    root = tree.getroot()

    ns = {'hp': 'http://www.hancom.co.kr/hwpml/2010/HWPML'}

    # Find follow-up paragraphs (contain "1." "2." "3.")
    followup_paras = []  # (para_element, old_number)
    modified_paras = []

    for para in root.findall('.//hp:p', ns):
        para_id = para.get('id', 'unknown')

        # Consolidate <hp:t> within each <hp:run> first
        for run in para.findall('.//hp:run', ns):
            consolidate_t_tags(run, ns)

        modified = False

        # Check if this is a follow-up line (starts with "1." "2." "3.")
        full_text = get_para_text(para, ns)
        if full_text.startswith('1.') or full_text.startswith('2.') or full_text.startswith('3.'):
            num = int(full_text.split('.')[0])
            followup_paras.append((para, num))
        else:
            # Also need to replace window dates in this section
            for run in para.findall('.//hp:run', ns):
                for t_tag in run.findall('hp:t', ns):
                    if t_tag.text:
                        orig_text = t_tag.text
                        new_text = orig_text

                        # Replace window dates
                        if old_values['window_start'] in orig_text:
                            new_text = new_text.replace(old_values['window_start'], updates['window_start'])
                        if old_values['window_end'] in orig_text:
                            new_text = new_text.replace(old_values['window_end'], updates['window_end'])

                        if new_text != orig_text:
                            t_tag.text = new_text
                            modified = True

        if modified:
            modified_paras.append(para)

    # Sort followup paragraphs by their number
    followup_paras.sort(key=lambda x: x[1])

    # Replace follow-up items
    for i, (para, old_num) in enumerate(followup_paras):
        if i < len(followups):
            new_item = followups[i]['item']
            # Find the first run with text and replace it
            for run in para.findall('.//hp:run', ns):
                for t_tag in run.findall('hp:t', ns):
                    if t_tag.text:
                        # Replace the entire text with new follow-up
                        t_tag.text = f"{i+1}. {new_item}"
                        break
                else:
                    continue
                break

            modified_paras.append(para)

    # Remove lineSegArray from all modified paragraphs
    for para in modified_paras:
        remove_lineSegArray(para, ns)

    # Write back
    tree.write(filepath, encoding='UTF-8', xml_declaration=True)

def consolidate_t_tags(run, ns):
    """Consolidate multiple <hp:t> tags within a run into one."""
    t_tags = run.findall('hp:t', ns)
    if len(t_tags) <= 1:
        return

    # Merge all text into the first t tag
    merged_text = ''
    for t_tag in t_tags:
        if t_tag.text:
            merged_text += t_tag.text

    # Set first tag text, remove others
    t_tags[0].text = merged_text
    for t_tag in t_tags[1:]:
        run.remove(t_tag)

def get_para_text(para, ns):
    """Get full text content of a paragraph."""
    texts = []
    for run in para.findall('.//hp:run', ns):
        for t_tag in run.findall('hp:t', ns):
            if t_tag.text:
                texts.append(t_tag.text)
    return ''.join(texts)

def remove_lineSegArray(para, ns):
    """Remove all lineSegArray elements from a paragraph using ElementTree API."""
    # ElementTree stores the tag with full namespace when parsing
    # We need to find elements by their tag, which includes the namespace
    hp_ns = 'http://www.hancom.co.kr/hwpml/2010/HWPML'

    # Find all child elements that have lineSegArray in their tag
    to_remove = []
    for child in list(para):  # Use list() to get a snapshot
        tag = child.tag
        # Check if this is a lineSegArray element (with or without namespace)
        if tag == f'{{{hp_ns}}}lineSegArray' or tag == 'lineSegArray' or 'linesegarray' in tag.lower():
            to_remove.append(child)

    for elem in to_remove:
        para.remove(elem)

    # Verify removal
    remaining = [child.tag for child in para if 'lineseg' in child.tag.lower()]
    if remaining:
        print(f"  Warning: lineSegArray elements still present: {remaining}")

def create_hwpx(extract_dir, output_path):
    """Create HWPX file from extracted contents."""
    mimetype_path = os.path.join(extract_dir, 'mimetype')

    with zipfile.ZipFile(output_path, 'w', zipfile.ZIP_DEFLATED) as zipf:
        # Find mimetype file
        mimetype_found = False
        for root, dirs, files in os.walk(extract_dir):
            for file in files:
                filepath = os.path.join(root, file)
                relpath = os.path.relpath(filepath, extract_dir)

                if file == 'mimetype':
                    # Add mimetype first with stored compression (no compression)
                    zipf.write(filepath, relpath, compress_type=zipfile.ZIP_STORED)
                    mimetype_found = True
                else:
                    zipf.write(filepath, relpath, compress_type=zipfile.ZIP_DEFLATED)

        if not mimetype_found:
            print("Warning: mimetype file not found")

