def get_text_recursive(element, ns):
    """Get all text from an element recursively."""
    texts = []
    hp_ns = 'http://www.hancom.co.kr/hwpml/2010/HWPML'
    for t in element.iter():
        if t.tag == f'{{{hp_ns}}}t':
            if t.text:
                texts.append(t.text)
    return '\n'.join(texts)

